function smallestEvenMultiple(n) {
  const remainder = n % 2;
  if (remainder === 0) {
    return n;
  }
  const doubled = n * 2;
  return doubled;
}

brute:
function smallestEvenMultiple(n) {
  // Count upward until a number is divisible by both 2 and n.
  let candidate = 1;
  while (candidate % 2 !== 0 || candidate % n !== 0) candidate++;
  return candidate;
}

